224	func rulesConflict(candidate, existing []Rule) bool {
225		for _, a := range candidate {
226			for _, b := range existing {
227				if a.Direction == b.Direction && a.Action != b.Action && portsOverlap(a.Ports, b.Ports) {
228					return true
229				}
230			}
231		}
232		return false
233	}
