238	// object key order is irrelevant (structs and maps encode deterministically)
239	// while the rules array order stays significant.
240	func contentKey(label string, rulesJSON, paramsJSON []byte) string {
241		return string(label) + "\x00" + string(rulesJSON) + "\x00" + string(paramsJSON)
242	}
