	}

	first := observe(t)

	// Repetition on a fresh database must produce identical externally visible
	// results.
	second := observe(t)
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("boundary sequence is not deterministic\nfirst run:  %#v\nsecond run: %#v", first, second)
	}
}
